ns.HELP = {
  { "С чего начать", {
    { sub = "Первые шаги" },
    { "Откройте это окно", "Введите /fl или нажмите кнопку у миникарты." },
    { "Изучите рецепты", "Откройте окно каждой профессии один раз на каждом персонаже." },
    { "Узнайте цены", "На аукционе нажмите «Полная проверка» (разрешается примерно каждые 15 минут)." },
    { "Подсказки", "Наведите на любой предмет, чтобы увидеть его стоимость для вас. В настройках можно включить короткий вид (сегодняшний минимум и стоимость для вас), Shift — остальное. Если лотов 20 и больше, продажа на аукционе оценивается по сегодняшним ценам; если меньше — по обычной цене месяца, если она ниже, чтобы пара надежд не вводила в заблуждение; серая строка об этом скажет. Что даёт распыление или изготовление, оценивается не выше обычной цены за эту неделю, поэтому скупка, взвинтившая цену материала, не сделает распыление выгодным." },
    { "Сумки", "Подсказка сумки показывает, сколько стоит один слот по сегодняшней минимальной цене (аукцион или торговец), и какая сумка сейчас дешевле всего за слот — чтобы сначала покупать самое дешёвое место." },
    { sub = "Настройки и вид" },
    { "Поиск", "В настройках и справке есть поиск над списком: введите две буквы или больше, чтобы увидеть всё, где это упоминается, сразу из всех разделов." },
    { "Настройки", "Боковая панель, как в EllesmereUI: сначала глобальные настройки (одинаковые для всех персонажей: комиссия аукциона, запас, источник цен и что считается перепродажей или сделкой), затем профили, затем страница на каждую часть аддона с вкладками сверху." },
    { "Темы", "Настройки, Внешний вид: FL Clean (плоская и тихая), FL Bronze (бронзовый край, золотые заголовки, секции-карточки, переключатели) или FL Gilded (бронзовая рамка, золотые заголовки с засечками), и цвет акцента: «Авто» берёт цвет EllesmereUI, если он установлен, или выберите свой. Новый вид появляется после перезагрузки; аддон предложит её. «Размер» делает окна меньше или больше, от 75% до 150%: перетащите и отпустите." },
    { "Профили", "Настройки, Профили: профиль — набор настроек, которым могут делиться персонажи, например без подсказок у одного и без поиска клиентов у другого. Каждый персонаж использует один (сначала «По умолчанию»). «Новый профиль» копирует текущие настройки; «Переименовать», «Сбросить» и «Удалить профиль» (клик дважды) действуют на профиль этого персонажа. «Экспорт и импорт» открывает одно окно: экспорт копирует профиль текстом с отмеченными частями; импорт создаёт новый профиль из чужого текста. Глобальные настройки в профиль не входят." },
    { sub = "Обновления" },
    { "Приветствие", "При первом открытии окна короткое приветствие перечисляет пять первых шагов. Показать снова — кнопка внизу слева на этой вкладке или /fl welcome." },
    { "Что нового", "После обновления чат один раз перечисляет новое в версии. Кнопка «Что нового» (внизу справа в справке и Обзоре) или /fl new покажет это карточкой." },
  } },
  { "Проверки аукциона", {
    { sub = "Проверка" },
    { "Полная проверка", "Читает все лоты за несколько секунд." },
    { "Пауза", "Останавливает слежение за перепродажами и собственные запросы очереди покупок, чтобы ваши поиски и открытая страница оставались как есть; «Купить», «Сейчас» и клик по строке работают. «Продолжить» возвращает всё назад, закрытие аукциона тоже завершает паузу. Чтобы проверить только то, что нужно вашим рецептам, введите /fl scan materials." },
    { "Слежение за перепродажами", "На аукционе: проверяет, пока он открыт, и звенит, когда появляется новая перепродажа торговцу. Между полными проверками (примерно каждые 15 минут) читает весь список аукциона примерно раз в 20 секунд, как поиск без названия на странице «Покупка», и присматривается ко всему, что только что стало достаточно дешёвым. Список приходит от дешёвого к дорогому, частями: новая перепродажа звенит и попадает в очередь покупок сразу, как приходит её часть, не дожидаясь остального. Пока список читается, на странице «Покупка» видны все предметы, от дешёвых; после вашего поиска он ждёт полминуты, прежде чем заменить ваши результаты. Проверять он может только при открытом аукционе: закрыли — пауза, вернулись — продолжает (Настройки, Аукцион: Возобновлять слежение за перепродажами). Он также ждёт, пока вы на странице покупки или продажи одного предмета, чтобы не менять то, что она показывает; строка состояния об этом скажет, а когда вы вернётесь к списку, он продолжит." },
    { "Тихий режим", "Занимаетесь чем-то ещё, пока ждёте звонка? /fl quiet выключает звук игры и играет звонки Forever Ledger на полной громкости даже в фоне, плюс звонок при выигрыше лота. Он держится у этого персонажа через перезагрузки и входы, пока вы снова не введёте /fl quiet. «Тихий режим во время слежения» (Настройки, Аукцион, Оповещения) делает это сам, и /fl pair предложит его включить. Настройки звука потом вернутся." },
    { "Другие аддоны", "Если полную проверку делает Auctionator или другой аддон, Forever Ledger читает и её. Если установлены Auctionator, TSM или ForeverForge, то, что они уже закрывают (например, цены аукциона в подсказках или звук при продаже лота), один раз выключается с сообщением; вернуть можно в Настройках." },
    { "Нейтральные аукционы", "Пиратская Бухта, Прибамбасск и Круговзор держат свои цены и берут 15% комиссии (ваша фракция — 5%), и стоимость, защита продажи и вкладка «Аукционы» считают их, пока вы там. Вкладка «Аукционы» перечисляет то, что у вас выставлено там, отдельно от вашей фракции." },
    { sub = "Продажа" },
    { "Ваши лоты", "Вкладка «Аукционы» рядом с аукционом: «Все», «Идут», «Перебиты» и «Проданы», как в журнале. У каждого лота видно, сколько, ваша цена за штуку, текущий минимум и «перебивают» (красным) или «минимум» (зелёным); у проданных — сколько вы получите после комиссии и когда золото придёт на почту. Нижняя строка говорит, сколько золота в пути и сколько ждёт на почте. «Проверить цены» проверяет их все; проверки и слежение тоже их проверяют, а о перебитом лоте придёт строка в чат и звук (Настройки, Аукцион). «Отменять следующие перебитые» спросит один раз, дальше каждый клик отменяет следующий (каждый теряет залог). При открытии аукциона чат скажет, что продалось без вас и сколько золота это принесло (Настройки, Аукцион). «Прокрутка — отменять» (при каждом визите выключено, Esc выключает): каждый тик колеса над списком отменяет следующий перебитый лот. «Отменять и те, где можно просить больше»: добавляет ваши лоты, которые самые дешёвые, но минимум на 10% ниже обычной цены (помечены «можно просить больше»), чтобы выставить их дороже. Средний клик по строке пропускает её в этот визит." },
    { "Звук продажи", "Звук монеты, когда продаётся один из ваших лотов. Настройки, Аукцион: Звук при продаже лота." },
    { "Помощь с ценой", "На вкладке «Продажа», под кнопкой создания лота: ваша обычная цена и текущий минимум, с кнопками «Перебить» (на 1 медь дешевле минимума) и «Обычная», которые подставляют цену. Если минимум заметно ниже обычной, он так и скажет — можно подождать. Выставить вы всё равно нажимаете сами (Настройки, Аукцион)." },
    { "Защита продажи", "На вкладке «Продажа», если торговец платит больше, чем принесёт ваш лот после комиссии, красная строка под «Выставить» скажет об этом, а кнопка будет неактивна, пока вы не нажмёте «Всё равно». Настройки, Аукцион: снимите «Останавливать выставление ниже цены торговца», чтобы осталось только предупреждение." },
  } },
  { "Подсказки", {
    { sub = "Цены" },
    { "Цена аукциона", "Аукцион, минимум: самая низкая цена на последней проверке, сколько лотов выставлено и (серым) как давно. Под ней, если отличается: среднее по 20 самым дешёвым, примерно то, что вы заплатите, покупая несколько. Стоимость в Forever Ledger считается по этому среднему, чтобы один случайный дешёвый лот её не сбивал. Если ваши цены старше 12 часов, берётся цена Auctionator или TSM, если они есть, и это будет указано." },
    { "Сколько стоит вам", "Лучшее из продажи на аукционе, продажи торговцу, распыления или изготовления чего-то, с несколькими лучшими способами. Распыление считает, за сколько продаются материалы, в среднем: каждое распыление даёт один результат, и подсказка показывает шанс каждого. Наведите на повреждённое снаряжение — способ через торговца посчитает, сколько он платит за него как есть. Настройки, Подсказки выбирают, какие способы считать (выключите изготовление, чтобы не учитывать то, что могут сделать альты); цепочки и очередь покупок по-прежнему считают все способы." },
    { "Совет по продаже", "У предметов в сумках первая строка Forever Ledger говорит, что с ними делать. «Оставить», если предмет ещё нужен заданию, нужен рецепту кого-то из ваших персонажей, вы за ним следите или он в одном из ваших списков. Иначе «Продать»: торговцу, на аукционе (он приносит заметно больше после комиссии и залога: на четверть, или вдвое, если продаётся медленно) или «На грани», когда способы близки, с причиной серым. Привязанные предметы говорят «торговец»; снаряжение, которое этот персонаж может носить, говорит, что делать, если вы не будете носить («Если не будете носить: продать торговцу» или распылить, когда это заметно выгоднее). Когда распыление приносит больше, это тоже видно, с именем вашего зачарователя; когда оно приносит на четверть больше или лучше, «Распылить» — первая строка, а продажа другим способом под ней. Это только совет: ничего не продаётся. Выключается в Настройках, Подсказках." },
    { "Залоги аукциона", "Продажа предмета на аукционе (его строка «Сколько стоит вам»), перепродажи и вид Пиратской Бухты допускают один 8-часовой лот, который не продастся (его залог потерян). Залог возвращается, когда лот продаётся. Материалы дальше по цепочке (пыль от распыления, результат изготовления) его не считают, поэтому поиск распыления, цепочки, перепродажи торговцу и лимиты списков не меняются. Если из-за этого продажа торговцу выгоднее, вариант говорит «Лучше торговцу». Залоги берутся из цены аукциона, когда она есть, иначе по формуле Classic, которая совпадает с Forever: 5% цены торговца за 2 часа (25% в Пиратской Бухте), то есть 20% за 8 часов. Без известной цены торговца — ноль." },
    { "Покупать по или ниже", "Самое большее, что стоит платить, после вашего запаса. Зелёным, когда уже дешевле." },
    { "Версии снаряжения", "Снаряжение со случайными характеристиками (например, «орла») показывает и цену именно этой версии." },
    { "История цен", "Удерживайте Ctrl над предметом: самая низкая цена за последние 14 дней, растёт она или падает, обычная цена в этом месяце, сколько лотов обычно выставлено и самая низкая цена за всё время. Копится с каждой проверкой." },
    { "Окно цены", "Alt+клик по предмету в сумках, по ссылке в чате или по лоту на аукционе (результаты поиска, лот снаряжения или картинка предмета на странице покупки; снаряжение со случайными характеристиками открывается на той версии, по которой вы кликнули) открывает его окно. Чтобы посмотреть любой предмет, даже которого у вас нет: «Поиск цены» вверху этого окна или /fl price, затем введите часть названия в поле справа вверху. Окно показывает обычную цену, куда она идёт, текущий минимум и сколько выставлено, сколько у вас и сколько выставлено вами; график минимальной и обычной цены по дням за 2 недели, 3 месяца или год (каждая проверка сохраняет день, а с включённой синхронизацией считаются и проверки второго аккаунта, с днями, пропущенными без игры, до 14, которые приходят при связи; дни хранятся 90 дней, затем недельными средними за год), с количеством лотов столбиками и пунктиром для цены торговца или стоимости распыления и затрат на изготовление; наведите — увидите каждый день. Снаряжение со случайными характеристиками может показать одну версию («орла»). Рядом: ваши последние 7 дней с предметом и сколько он стоит для вас. Если его делает рецепт: материалы по сегодняшним ценам, сколько стоит изготовить один против того, за сколько он продаётся после комиссии и одного непроданного лота (как считает «Сколько стоит вам»), и прибыль; клик по материалу — его график. Выберите, сколько изготовлений и в какой список добавить материалы. «Поиск на аукционе» покажет его там, пока аукцион открыт. Настройки, Подсказки, Общие выключают клик или меняют его на Ctrl+клик или Ctrl+Alt+клик (если другой аддон, например распыляющий, использует Alt+клик). Ctrl+клик тогда больше не открывает примерочную; при Ctrl+Alt+клике Ctrl+клик по-прежнему её открывает." },
    { sub = "Использование и задания" },
    { "Также", "Результаты распыления, какие ваши рецепты его используют, и самое дешёвое заполнение ящика." },
    { "Задания и изготовление", "Предметы, которые просят задания (бронзовая трубка, паучий ихор, флакон масла...), говорят «Задания (3)» оранжевым, а предметы, которые используют рецепты, — «Используется в изготовлении (12)» с профессиями (все рецепты, которые мы знаем, ваши или нет). Удерживайте Shift для списков: каждое задание, его уровень и сколько, для вашей фракции, и изготовления по профессиям, с тем, кто из ваших персонажей их использует. Задания становятся жёлтыми с «оставить», когда этот персонаж ещё не дорос до уровня, чтобы вы их не продали. Задания, которые этот персонаж уже сделал, серые для его уровня и задания других классов, не показываются (Настройки, Подсказки: Только задания, которые ещё нужны этому персонажу; выкл показывает все, с пометками). Качающиеся игроки покупают это раз на персонажа, поэтому оно продаётся; подсказка сделки скажет, когда сделка из таких. Из заданий оригинального Classic: Forever мог что-то изменить." },
    { "Ярмарка Новолуния", "Предметы, которые Ярмарка Новолуния берёт за призовые билеты, получают кораллово-красную строку: сколько нужно на сдачу, сколько билетов дают и кто берёт (маленькая пушистая лапка: 5 за 1 билет, Йеб Неблегир). Части животных, а также изготовления кузнечного дела, инженерного дела и кожевничества. Список Classic: Forever мог его изменить. Настройки, Подсказки." },
    { "Сбыт", "Как быстро продаётся предмет: «Быстро», «Ровно», «Медленно», «Редко» (редко выставляется, уходит быстро) или «Продаж не видно», в сравнении с предметами того же вида, чтобы руда и мечи не сравнивались по одной мерке. Считаются лоты, исчезнувшие раньше, чем могли истечь, поэтому копится с полными проверками (быстрее всего со слежением) и показывается после 3 часов сравнения проверок (а в первый день — минимум после 3 продаж)." },
  } },
  { "Вкладка «Заработок»", {
    { "Вкладка «Заработок»", "Все способы заработать, которые находит Forever Ledger, одним списком: изготовления, которые продаются торговцу или на аукционе, превращения, перепродажи торговцу, сделки заметно ниже обычной цены, распыление и Пиратская Бухта против вашего аукциона. В каждой строке: сколько стоит, сколько приносит, прибыль за раз и сколько раз это можно сделать с тем, что сейчас выставлено достаточно дёшево. Клик по названию столбца — сортировка; сначала прибыль, умноженная на количество. Считается при открытии вкладки («Обновить» — пересчитать). Заменяет вкладки «Цепочки» и «Сделки»: /fl deals пока открывает старую вкладку «Сделки»." },
    { "Виды и фильтры", "Кнопки сверху выбирают вид и показывают, сколько их; «Всё» не включает Пиратскую Бухту (до неё нужно добраться, и считаются только цены за последние 3 дня). «Мин. прибыль» скрывает мелкие, а поле профессии показывает изготовления одной профессии (распыление считается наложением чар). Снимите «Только мои рецепты», чтобы добавить изготовления всех профессий, которые продаются торговцу дороже материалов, из рецептов, которых у вас пока нет (помечены «выучить»). Поиск сужает по названию." },
    { "Сохранённые фильтры", "Выберите фильтры и нажмите «Сохранить фильтры»: они станут быстрой кнопкой (до 5). Клик — применить, правый клик — удалить." },
    { "Из чего складывается", "Клик по изготовлению: панель справа считает самый дешёвый способ достать материалы на столько изготовлений (начинается с того, что выставлено достаточно дёшево, а для изготовления на аукцион — не больше примерно дневных продаж; меняется в «Изготовлений»). Каждый материал набирается по одной единице из самого дешёвого места по очереди: из сумок (по цене, за которую его можно продать, или бесплатно с «Считать сумки бесплатными»), из следующего лота на аукционе, у торговца или изготовлением из своих материалов. Так несколько дешёвых рулонов рунной ткани покупаются, а остальное делается из ткани, и ничего не считается дважды. «Материалы в список покупок» кладёт купленное в новый список, каждый до самой высокой цены из плана." },
    { "Другие виды", "Клик по сделке, перепродаже, распылению или строке Пиратской Бухты — цифры и почему. Правый клик по любой строке (или «Окно цены») — окно цены предмета." },
  } },
  { "Цепочки и перепродажи торговцу", {
    { "Цепочки", "Купите материалы, изготовьте, распылите или превратите и продайте — по прибыли в час. Клик по строке — все шаги. Blizzard ослабил большинство цепочек через торговцев, поэтому «Продажа торговцу» часто будет пустой. Отметьте там «Все профессии», чтобы увидеть изготовления всех профессий, которые продаются торговцу дороже материалов, кто бы их ни знал. Рецепты из ваших окон профессий идут первыми. Те, которых ваши окна не показывали, берутся из данных игры и помечены «(Forever)», а для предмета без них — из Classic, с пометкой «(Classic)». Некоторые, возможно, ещё нельзя выучить в игре." },
    { "В список покупок", "Откройте цепочку или перепродажу торговцу, выберите обычный список или «Новый список», сколько изготовлений (или предметов), затем «В список покупок». Добавляются покупки и пределы цен; у существующего предмета сохраняются купленное количество и любая введённая вами цена. Группа распыления берёт свой самый дешёвый предмет. Списки ящиков и списки с «Любой ценой» не добавляются. Новые списки начинаются с выключенной покупкой: проверьте «Надо» и «До» и отметьте «Покупать из этого списка», когда будете готовы." },
    { "Перепродажи торговцу", "То, что на аукционе стоит дешевле, чем платит торговец. Они в очереди покупок рядом с аукционом (вид «Перепродажи торговцу»); полная проверка, которая их находит, открывает её, если она закрыта, а слежение звенит. Настройки, Общие настройки, Перепродажи и сделки задают минимальную прибыль, ради которой стоит тратить время, долей цены торговца и суммой." },
    { "На аукционе", "Лоты, которые стоит купить, получают зелёную полосу и значок с причиной (FLIP, DE, CRAFT, USE), а строка выше говорит, сколько их осталось." },
  } },
  { "Очередь покупок и списки", {
    { sub = "Очередь покупок" },
    { "Очередь покупок", "Нажмите вкладку «Покупка» внизу окна аукциона, после вкладок Blizzard «Покупка», «Продажа» и «Аукционы» (рядом «Мои лоты» показывает ваши лоты; если в настройках вкладки Forever Ledger в аукционе выключены, нажмите «Очередь покупок» под окном — панель откроется рядом). Она выстраивает перепродажи торговцу и ваши списки покупок. В каждой строке: «До» (самое большее, что она платит за штуку), «Купить» (сколько она купила бы сейчас: что выставлено по этой цене или ниже, не больше, чем хочет список или позволяет ваше золото) и «Итого» (сколько это стоит). Следующий лот она находит сама, а клик по «Купить» (или, с отмеченной «Прокруткой — покупать», тик колеса вверх или вниз над «Перепродажами торговцу» или над верхней полосой списка покупок) покупает его. Стопка материалов подтверждается тем же тиком, когда итоговая цена возвращается в предел (чтобы подтверждать самому, отметьте «Подтверждать стопки вторым щелчком» в Настройках, Аукцион). Внизу справа: что вы купили за этот визит, сколько это стоило и прибыль, если сдать торговцу (наведите — цифры). /fl queue. У каждой строки есть звезда: клик — следить за предметом (золотая, пока следите; слежение ищет его при каждом чтении аукциона), и короткая причина: FLIP, WATCH (или название списка покупок)." },
    { "Разовый поиск", "Вид «Разовый поиск» на вкладке «Покупка» — чтобы посмотреть, а не ловить. «Проверить» один раз читает весь список аукциона (при включённом слежении цены уже свежие), и список остаётся таким, каким его прочитали, пока вы не проверите снова. Отметьте группы слева («Все предметы», «Все группы», «Материалы», «Ткань»...; группа считает и вложенные, отмеченные складываются, + раскрывает группу) и ищите по названию справа вверху. У каждого предмета: минимальная цена, обычная цена, насколько она ниже или выше неё (зелёным ниже 90%, красным выше 110%), сколько выставлено и FLIP, WATCH или DEAL, если слежение его купило бы. Лучшие сделки первыми. Клик по строке — окно цены; клик по звезде — следить." },
    { "Выставить", "Вкладка «Выставить» в окне аукциона: ваши сумки, разложенные по группам («Ткань», «Травы», «Снаряжение»...), у каждого предмета готовая цена и пометка от совета по продаже («Выставить», «Оставить», «Торговец», «Распылить»; «Показать: всё» перечисляет всё, что можно выставить). Цена берётся из правила выставления предмета: такая же, как минимум (лоты по одной цене продаются в порядке выставления; правило может перебивать), никогда ниже 70% обычной цены или того, что платит торговец после комиссии; ниже — не выставляется. Выбор предмета ищет его на аукционе, как страница продажи, и цена берётся из текущих лотов («Выставить» ждёт этого); таблица ниже перечисляет их: цена за штуку, сколько и продавец, ваши отмечены, со строкой, куда встал бы ваш; клик по лоту — поставить такую же цену, «Обновить» — посмотреть снова. Меняйте количество, цену или срок (2 ч, 8 ч, 24 ч) и смотрите залог, общую цену и сколько вы получите после комиссии; строка под этим говорит, откуда цена и по какому правилу. «Выставить» выставляет и переходит к следующему; «Пропустить» и «Назад» двигают дальше; средний клик по строке пропускает её в этот визит. «Прокрутка — выставлять» (при каждом визите выключено, Esc выключает): каждый тик колеса над списком выставляет выделенный предмет. Один клик или тик на лот, как требует игра; когда игра просит подтверждение, следующий клик или тик подтверждает." },
    { "Группы", "Вкладка «Группы» раскладывает предметы по группам и даёт каждой правила. Встроенные группы («Материалы», «Ткань», «Травы», «Расходники», «Рецепты», «Снаряжение»...) сортируются по типу предмета игры, снаряжение — по виду и затем по требуемому уровню (уровень 1-15 до 56-60); группы профессий («Портняжное дело: материалы», «Портняжное дело: изготовление») берутся из рецептов; «Отслеживаемые» и «Серые предметы»; и ваши группы («Новая группа»). Выберите группу: «Предметы» перечисляет, что в ней (добавить предмет по названию, номеру или Shift+клику; «Убрать из группы»; «Вернуть предметы» возвращает встроенную группу), «Правила» — четыре карточки: выставление, покупка, торговец и изготовление, каждая «Как выше», «По умолчанию Forever Ledger», «Выкл», «Изменено здесь» (правка поля) или одно из ваших сохранённых правил. «Правила» слева перечисляет наборы по умолчанию (скопируйте, чтобы сделать свой) и ваши сохранённые правила, которые могут использовать несколько групп. Если предмет в нескольких группах, побеждает ваша группа, затем группа профессии, затем встроенная. Вкладка «Выставить» сегодня использует правила выставления; «Вернуть встроенные» и удаление спрашивают подтверждение." },
    { "Проверка из панели", "В нижней строке панели — «Следить», «Полная проверка» и «Пауза» («Остановить» и «Продолжить», пока они включены), а прогресс проверки чуть выше. Пока панель открыта рядом с аукционом, те же кнопки под окном аукциона скрыты." },
    { "Отслеживаемые предметы", "Предметы, которые вы всегда хотите проверять, у каждого — самое большее, что вы заплатите (скажем, шёлковая ткань до 2с на бинты). Слежение ищет их при каждом чтении аукциона (примерно раз в 20 секунд), и всё по вашей цене или дешевле попадает в «Перепродажи торговцу» первыми и звенит. Оставьте цену «торговец», чтобы покупать только когда торговец даёт больше. Добавьте предмет кнопкой «Следить» в окне цены или кнопкой «Отслеживаемые» вверху «Перепродаж торговцу» (Shift+клик, перетаскивание или ввод); там же меняется «До» и удаление. Для снаряжения покупается любая версия характеристик по вашей цене или дешевле." },
    { "Два вида", "«Перепродажи торговцу» или «Списки покупок», переключаются вверху панели, по одному; покупает тот вид, который открыт, поэтому список никогда не купит перепродажу случайно. У каждого свои кнопки внизу. Когда есть что купить, полоса вверху светится (золотым для «Перепродаж торговцу», фиолетовым для «Списков покупок»); с отмеченной «Прокруткой — покупать» она показывает и колесо: прокручивайте над «Перепродажами торговцу» (полосу справа можно тянуть, чтобы листать список) или над верхней полосой списка покупок. Новая перепродажа со звонком переключает панель на «Перепродажи торговцу», если вы не в списке покупок (что-то из него ищется или покупается, либо вы кликали или прокручивали там последние 30 секунд); тогда золотое число на кнопке «Перепродажи торговцу» (и на вкладке «Покупка») говорит, что оно там." },
    { "Безопасно по замыслу", "Он никогда не платит больше показанного предела (проверяется ещё раз по итоговой цене) или больше, чем у вас есть, и каждая покупка начинается с вашего тика или клика, как требует Blizzard. «Прокрутка — покупать» работает, только когда мышь над «Перепродажами торговцу» или верхней полосой списка покупок; снимите отметку, чтобы покупать только кликом. Правый клик по предмету — пропустить его. Предметы, на которые пока не хватает, остаются внизу списка, серые и помечены «не хватает золота», и пропускаются, пока золото не появится; прокрутите за последний доступный — услышите звук ошибки и красное сообщение, один раз." },
    { "Потратить не более", "Поле внизу очереди покупок ограничивает, сколько она потратит за этот визит на аукцион (введите 50 для 50g; при каждом открытии аукциона начинается заново). Пока ничего не введено, предела нет; остаток показывается рядом. Предметы сверх него помечены «выше лимита» и пропускаются. Чтобы всегда оставлять золото на ремонт или транспорт: Настройки, Аукцион, Очередь покупок: всегда оставлять." },
    { sub = "Списки покупок" },
    { "Списки покупок", "Именованные списки предметов, например снаряжение для твинка или расходники на рейд. Выберите список в меню вверху; «Новый», «Переименовать» и «Удалить» рядом. С открытым списком Shift+кликните предмет, чтобы добавить (или перетащите, или введите название: имена предлагаются по мере ввода, Enter берёт верхнее). Открывайте их где угодно, чтобы планировать до аукциона: кнопка «Списки покупок» вверху этого окна, Shift+клик по кнопке миникарты или /fl lists." },
    { "Искать всё", "Проверяет на аукционе всё из списка сразу. У каждого предмета видно, когда его проверяли («проверяю...» и «в очереди», пока идёт), сколько выставлено и минимум. Клик по предмету — посмотреть его на аукционе." },
    { "Есть", "Сколько у вас каждого предмета: сумки и банк этого персонажа, покупки на аукционе, ещё лежащие на почте, и ваши персонажи этого режима и фракции. В списке, из которого вы покупаете, это читается как 3 (20): 3 куплено для списка, 20 всего. Наведите на число, чтобы увидеть где. Это для сведения, на покупки не влияет." },
    { "Покупка из списка", "Отметьте «Покупать из этого списка» в очереди покупок: список добавляет «Надо» (сколько купить) и «До» (самое большее, что вы заплатите за штуку: заполняется из источника; наведите, чтобы увидеть откуда; «выкл» — не покупать), и вид «Списки покупок» в очереди покупает их. «Надо» — сколько купить, сколько бы у вас ни было; «Есть» показывает, сколько уже куплено. Больше, чем «Надо», он не покупает. Введите «любая» в «Надо», чтобы покупать всегда по «До» или дешевле без предела (не с «До» = «любая», иначе он купил бы все лоты: тогда покупается один). Предмет готов, когда «Надо» куплено, и остаётся готовым; «Купить снова» (внизу справа) начинает список заново. Нижняя строка говорит, примерно сколько будет стоить докупить остальное." },
    { "Откуда берётся «До»", "Наведите на «До», чтобы увидеть источник. От цепочки: её потолок покупки, а не сегодняшняя цена; если предмет нужен двум цепочкам, берётся меньший. Добавьте цепочку снова или нажмите «Купить снова», чтобы обновить. Добавлено вручную: обычная цена плюс допуск списка («Платить до X% к обычной цене», начиная с 10%); меняйте процент в каждом списке, затем включите покупку или нажмите «Купить снова». Своя цена, включая «выкл», всегда важнее и автоматически не меняется. Если маршрут цепочки больше нельзя оценить, он отключается до обновления с известными ценами." },
    { "Цены", "Вводите цену как удобно: 2g 50s 25c, 2 50 25 или 2.50.25 (золото серебро медь), 2 50 (золото серебро), 25s, 75c или просто число для золота; при Enter всё приводится к виду, а подсказка покажет результат. Введите «любая» для цены или отметьте «Любая цена» внизу списка (подготовка к рейду): очередь купит самое дешёвое до нужного количества, но не дороже трёх обычных цен." },
    { "Товары торговцев", "Товары торговцев с бесконечным запасом показывают «торговец» в «До» и не попадают в очередь аукциона, включая добавленные вручную. Настройки > Аукцион > Покупка: «Покупать товары торговцев и на аукционе» (по умолчанию выкл) разрешает покупку по цене торговца; ваша цена ниже или «выкл» всё равно соблюдается. Сохранённая цена остаётся. Правый клик по полю «До» возвращает автоматическую цену; подсказка показывает потолок цепочки или обычную цену с допуском, пока действует ваша цена. Товары с ограниченным запасом остаются обычными лотами." },
    { "Купить или изготовить", "У предметов из ваших рецептов есть кнопка «Купить/Изготовить»: выберите «Изготовить», и список покажет материалы на нужное количество, с «До» для каждого (обычная цена плюс допуск списка, если не ввели свою) и сколько куплено. Материалы, которые продаёт торговец, помечены «торговец». Наведите на предмет из рецепта: сколько стоит купить его против покупки материалов на изготовление и что дешевле." },
    { "Одна версия", "Введите «Soldier's Armor of the Monkey» или сделайте shift-клик по ссылке нужной версии, чтобы оставить в списке только её. «Искать всё» проверяет все версии снаряжения; наведите на предмет — цены каждой версии, ваша первой." },
    { "Поделиться и импорт", "«Поделиться / импорт» вверху справа открывает окно с двумя вкладками. «Поделиться» копирует список простым текстом для Discord или другу; «Импорт» читает его обратно (или простой список названий, номеров предметов или ссылок Wowhead по одному в строке). Импорт никогда не меняет ваши списки и сам не покупает: отметьте «Покупать из этого списка»." },
  } },
  { "Сделки", {
    { "Вкладка «Сделки»", "Лоты заметно ниже обычной минимальной цены предмета — для покупки и перепродажи: цена сейчас, обычный минимум, сколько лотов стоит купить, прибыль после комиссии и одного непроданного лота и насколько это надёжно (хорошо, средне или мало данных)." },
    { "Бухта Боти", "Вкладка «Сделки», «Бухта Боти» (вверху справа): нейтральный аукцион против вашего, каждый после своей комиссии (там 15%, здесь 5%) и одного непроданного лота. «Там продаётся дороже»: предметы минимум на 10% выгоднее при продаже в Бухте Боти. «Там дешевле»: купить там, продать здесь. Цены берутся из проверок там и хранятся отдельно; строка подсказки для больших разниц — в Настройках, Подсказки." },
